+  const [authChecked, setAuthChecked] = useState(() => !session?.token);
+
+  useEffect(() => {
+    if (!session?.token) {
+      setAuthChecked(true);
+      return undefined;
+    }
+
+    let cancelled = false;
+    setAuthChecked(false);
+    void systemClient.me()
