+  token: 'tenant-b-token',
+  scope: 'tenant',
+  tenant: { id: 'tenant_b', slug: 'tenant-b', display_name: 'Tenant B' },
+  user: {
+    id: 'user-b',
+    tenant_id: 'tenant_b',
+    username: 'admin',
+    display_name: 'Tenant B admin',
+    role: 'admin',
+    must_change_password: false,
+    avatar_url: null,
+  },
